import csv, math, sys, os, numpy as np

filename = 'yacht_hydrodynamics.csv'

with open(filename, newline='') as f:
    reader = csv.DictReader(f)
    values = []
    for row in reader:
        val = row.get('froude_number')
        if val is None:
            continue
        try:
            values.append(float(val))
        except ValueError:
            pass

if not values:
    print('No values found')
else:
