import re, os
filename='nethakah__nasdaq-pipeline__timing_route.rpt'
text=open(filename).read()
values=[]
for line in text.splitlines():
    if line.strip().startswith('Hold'):
        m=re.search(r'Worst Slack\s*([0-9.+-]+)ns', line)
        if m:
            values.append(float(m.group(1)))
print('Hold worst slack values:', values)
if values:
    print('min', min(values), 'max', max(values))

